#include <iostream>
#include <vector>
using namespace std;

template <typename T>
T largest(const vector<T>& v) {
    T best = v[0];
    for (const T& x : v)
        if (x > best) best = x;
    return best;
}

template <typename T>
T smallest(const vector<T>& v) {
    T best = v[0];
    for (const T& x : v)
        if (x < best) best = x;
    return best;
}

int main() {
    int n;
    cin >> n;
    vector<long long> a;
    for (int i = 0; i < n; i++) {
        long long x;
        cin >> x;
        a.push_back(x);
    }
    long long hi = largest(a);
    long long lo = smallest(a);
    cout << hi << "\n" << lo << "\n" << hi - lo << "\n";
    return 0;
}
